function fusionnerSansClones(tapis) {
  const maxi = {};
  for (const tapisCourant of tapis) {
    const compte = {};
    for (const numero of tapisCourant) {
      compte[numero] = (compte[numero] || 0) + 1;
    }
    for (const cle in compte) {
      if (!(cle in maxi) || compte[cle] > maxi[cle]) {
        maxi[cle] = compte[cle];
      }
    }
  }
  const numeros = Object.keys(maxi).map(Number).sort((a, b) => a - b);
  const resultat = [];
  for (const numero of numeros) {
    for (let i = 0; i < maxi[numero]; i++) {
      resultat.push(numero);
    }
  }
  return resultat;
}

