def fusionner_sans_clones(tapis):
    maxi = {}
    for tapis_courant in tapis:
        compte = {}
        for numero in tapis_courant:
            compte[numero] = compte.get(numero, 0) + 1
        for cle in compte:
            if cle not in maxi or compte[cle] > maxi[cle]:
                maxi[cle] = compte[cle]
    resultat = []
    for numero in sorted(maxi):
        for _ in range(maxi[numero]):
            resultat.append(numero)
    return resultat

